def parse_count(text):
    try:
        count = int(text)
    except ValueError as error:
        raise ValueError('count must be integer text') from error
    if count < 0:
        raise ValueError('count must be nonnegative')
    return count

for raw_count in ['4', 'oops', '-1']:
    try:
        count = parse_count(raw_count)
    except ValueError as error:
        print('invalid:', error)
    else:
        print('accepted:', count)

class Ledger:
    def __init__(self):
        self.balance = 0
        self.history = []

    def deposit(self, amount):
        if type(amount) is not int or amount <= 0:
            raise ValueError('deposit must be a positive integer')
        self.balance += amount
        self.history.append(amount)

first = Ledger()
second = Ledger()
first.deposit(5)
print(first.balance, second.balance)
print(first.history, second.history)
try:
    first.deposit(-2)
except ValueError:
    print('rejected', first.balance, first.history)

import unittest

def rank_scores(records):
    for name, score in records:
        if type(score) is not int or not 0 <= score <= 100:
            raise ValueError('invalid score')
    return sorted(records, key=lambda record: -record[1])

class RankingTests(unittest.TestCase):
    def test_contract(self):
        records = [('Mira', 90), ('Ada', 90), ('Lin', 75)]
        self.assertEqual(rank_scores(records), records)
        self.assertEqual(rank_scores([]), [])
        self.assertEqual(records[0], ('Mira', 90))
        with self.assertRaises(ValueError):
            rank_scores([('Noor', 101)])

result = unittest.TestResult()
unittest.defaultTestLoader.loadTestsFromTestCase(RankingTests).run(result)
print(result.testsRun, result.wasSuccessful())
